function timestamp(seconds) {
  const milliseconds = Math.round(seconds * 1000);
  const hours = Math.floor(milliseconds / 3600000);
  const minutes = Math.floor((milliseconds % 3600000) / 60000);
  const wholeSeconds = Math.floor((milliseconds % 60000) / 1000);
  const remainder = milliseconds % 1000;
  return [hours, minutes, wholeSeconds].map((value) => String(value).padStart(2, '0')).join(':')
    + `,${String(remainder).padStart(3, '0')}`;
}

function srtText() {
  return NARRATION_CUES.map(([start, end, text], index) => (
    `${index + 1}\n${timestamp(start)} --> ${timestamp(end)}\n${text}\n`
  )).join('\n');
}

function continuousNarration() {
  return NARRATION_CUES.map(([, , text]) => text).join('');
}

function cueTimingPlan() {
  return {
    targetDurationSeconds: 60,
    safetyMarginSeconds: 0.1,
    voice: { name: 'Microsoft Kangkang', culture: 'zh-CN', gender: 'Male' },
    cues: NARRATION_CUES.map(([start, end, text], index) => ({ index: index + 1, start, end, text })),
  };
}

function markdownText() {
  const rows = NARRATION_CUES.map(([start, end, text], index) => (
    `| ${timestamp(start).replace(',', '.')}–${timestamp(end).replace(',', '.')} | ${VISUALS[index]} | ${text} |`
  ));
  return [
    '# 腕上节律：官方模拟器健康数据演示文字稿',
    '',
    '| 时间码 | 画面 | 旁白 |',
    '| --- | --- | --- |',
    ...rows,
    '',
    '## 连续旁白',
    '',
    continuousNarration(),
    '',
  ].join('\n');
}

function writeIfAbsentOrIdentical(filePath, content) {
  if (fs.existsSync(filePath)) {
    if (fs.readFileSync(filePath, 'utf8') !== content) {
      throw new Error(`Existing artifact has different content and will not be replaced: ${filePath}`);
    }
    return;
  }
  fs.writeFileSync(filePath, content, 'utf8');
}

function writeTextArtifacts(outputDirectory = OUTPUT_DIRECTORY) {
  fs.mkdirSync(outputDirectory, { recursive: true });
  const artifacts = {
    srtPath: path.join(outputDirectory, SRT_FILENAME),
    markdownPath: path.join(outputDirectory, MARKDOWN_FILENAME),
    narrationPath: path.join(outputDirectory, NARRATION_FILENAME),
    cuePlanPath: path.join(outputDirectory, CUE_PLAN_FILENAME),
  };
  const contents = {
    [artifacts.srtPath]: srtText(),
    [artifacts.markdownPath]: markdownText(),
    [artifacts.narrationPath]: continuousNarration(),
    [artifacts.cuePlanPath]: `${JSON.stringify(cueTimingPlan(), null, 2)}\n`,
  };
  for (const [filePath, content] of Object.entries(contents)) {
    if (fs.existsSync(filePath) && fs.readFileSync(filePath, 'utf8') !== content) {
      throw new Error(`Existing artifact has different content and will not be replaced: ${filePath}`);
    }
  }
  for (const [filePath, content] of Object.entries(contents)) writeIfAbsentOrIdentical(filePath, content);
  return artifacts;
}

function readPcmWavMetadata(wav) {
  if (!Buffer.isBuffer(wav) || wav.toString('ascii', 0, 4) !== 'RIFF' || wav.toString('ascii', 8, 12) !== 'WAVE') {
    throw new Error('Expected a RIFF/WAVE buffer');
  }
  const dataOffset = wav.indexOf(Buffer.from('data'));
  if (dataOffset < 0 || dataOffset + 8 > wav.length) throw new Error('WAV data chunk is missing');
  const byteRate = wav.readUInt32LE(28);
  const dataSize = wav.readUInt32LE(dataOffset + 4);
  if (!byteRate || dataOffset + 8 + dataSize > wav.length) throw new Error('WAV data chunk is invalid');
  return {
    audioFormat: wav.readUInt16LE(20),
    channels: wav.readUInt16LE(22),
    sampleRate: wav.readUInt32LE(24),
    byteRate,
    bitsPerSample: wav.readUInt16LE(34),
    dataSize,
    durationSeconds: dataSize / byteRate,
  };
}

function assembleCuePcmTimeline({ cues, sampleRate, channels, bitsPerSample, durationSeconds }) {
  const bytesPerFrame = channels * (bitsPerSample / 8);
  const byteRate = sampleRate * bytesPerFrame;
  const dataSize = durationSeconds * byteRate;
  if (!Number.isInteger(dataSize) || !Array.isArray(cues) || !byteRate) throw new Error('Invalid PCM timeline parameters');
  const wav = Buffer.alloc(44 + dataSize);
  wav.write('RIFF', 0, 'ascii');
  wav.writeUInt32LE(36 + dataSize, 4);
  wav.write('WAVEfmt ', 8, 'ascii');
  wav.writeUInt32LE(16, 16);
  wav.writeUInt16LE(1, 20);
  wav.writeUInt16LE(channels, 22);
  wav.writeUInt32LE(sampleRate, 24);
  wav.writeUInt32LE(byteRate, 28);
  wav.writeUInt16LE(bytesPerFrame, 32);
  wav.writeUInt16LE(bitsPerSample, 34);
  wav.write('data', 36, 'ascii');
  wav.writeUInt32LE(dataSize, 40);
  for (const cue of cues) {
    if (!Buffer.isBuffer(cue.pcm) || cue.pcm.length % bytesPerFrame) throw new Error('Cue PCM is invalid');
    const offset = cue.start * byteRate;
    const windowLength = (cue.end - cue.start) * byteRate;
    if (!Number.isInteger(offset) || !Number.isInteger(windowLength) || cue.pcm.length > windowLength || offset < 0 || offset + cue.pcm.length > dataSize) {
      throw new Error('Cue PCM does not fit its timeline window without trimming');
    }
    cue.pcm.copy(wav, 44 + offset);
  }
  return wav;
}

if (require.main === module) {
  console.log(JSON.stringify(writeTextArtifacts(OUTPUT_DIRECTORY), null, 2));
}

module.exports = {
  OUTPUT_DIRECTORY,
  EDIT_SEGMENTS,
  NARRATION_CUES,
  timestamp,
  srtText,
  continuousNarration,
  cueTimingPlan,
  markdownText,
  readPcmWavMetadata,
  assembleCuePcmTimeline,
  writeTextArtifacts,
};

