const media = require('../tools/health-demo-media.js');
const compose = require('../tools/compose-official-health-demo.js');

const composedPaths = {
  frameDirectory: path.join(compose.OUTPUT_DIRECTORY, 'raw-frames-test'),
  intermediatePath: path.join(compose.OUTPUT_DIRECTORY, 'intermediate-test.mkv'),
  masterPath: path.join(compose.OUTPUT_DIRECTORY, 'master-test.mp4'),
  narrationPath: path.join(compose.OUTPUT_DIRECTORY, 'narration-test.wav'),
  subtitlePath: path.join(compose.OUTPUT_DIRECTORY, 'subtitles-test.srt'),
  finalPath: path.join(compose.OUTPUT_DIRECTORY, 'final-test.mp4'),
};
const intermediateArguments = compose.buildIntermediateArguments(composedPaths);
assert.strictEqual(intermediateArguments.filter((argument) => argument === '-i').length, 1, 'raw frames have one image-sequence input');
assert.ok(intermediateArguments.includes('-framerate') && intermediateArguments.includes('10'), 'raw frames encode at 10 fps');
assert.ok(intermediateArguments.includes('ffv1'), 'intermediate uses a lossless video codec');

const masterArguments = compose.buildMasterArguments(composedPaths);
const filterGraph = masterArguments[masterArguments.indexOf('-filter_complex') + 1];
assert.strictEqual((filterGraph.match(/trim=start=/g) || []).length, 8, 'master graph contains all eight edit trims');
assert.match(filterGraph, /concat=n=8:v=1:a=0/, 'master graph concatenates eight clips');
assert.match(filterGraph, /scale=932:932:flags=lanczos/, 'master scales with Lanczos');
for (const [start, end] of media.EDIT_SEGMENTS) {
  assert.match(filterGraph, new RegExp(`trim=start=${start}:end=${end},setpts=PTS-STARTPTS`), `master trims ${start}-${end} seconds exactly`);
}
assert.ok(masterArguments.includes('libx264') && masterArguments.includes('yuv420p'), 'master is H.264 yuv420p');
assert.ok(masterArguments.includes('-an'), 'master is silent');

const finalArguments = compose.buildFinalArguments(composedPaths);
assert.ok(finalArguments.includes('aac'), 'final contains AAC narration');
assert.ok(finalArguments.includes('mov_text'), 'final embeds mov_text subtitles');
assert.ok(finalArguments.includes('language=zho'), 'subtitle language is Chinese');
assert.ok(finalArguments.includes('-sub_charenc') && finalArguments.includes('UTF-8'), 'final reads the subtitle source as UTF-8');
assert.ok(finalArguments.includes('+faststart'), 'final enables fast start');
const finalFilterGraph = finalArguments[finalArguments.indexOf('-filter_complex') + 1];
assert.doesNotMatch(finalFilterGraph, /atrim/, 'accepted narration is never trimmed during final muxing');
assert.ok(!finalArguments.includes('-t'), 'final mux has no output-duration trim');

