+const fs = require('fs');
+const path = require('path');
+const cp = require('child_process');
+const assert = require('assert');
+const crypto = require('crypto');
+const root = path.resolve(__dirname, '../../..');
+const compose = require(path.join(root, 'tools/compose-official-health-demo'));
+const capture = require(path.join(root, 'tools/capture-official-health-demo'));
+const media = require(path.join(root, 'tools/health-demo-media'));
+const base = '腕上节律-官方模拟器健康数据演示-';
+function write(name, content) { fs.writeFileSync(path.join(__dirname, name), content, { flag: 'wx' }); }
+function ffmpeg(args, allowed = [0]) {
+  const result = cp.spawnSync(compose.FFMPEG_PATH, args, { encoding: 'utf8', maxBuffer: 8 * 1024 * 1024 });
+  assert.ok(allowed.includes(result.status), result.stderr);
+  return result;
+}
+function pcm(file) {
+  const wav = fs.readFileSync(file);
+  const offset = wav.indexOf(Buffer.from('data'));
+  return { metadata: media.readPcmWavMetadata(wav), data: wav.subarray(offset + 8, offset + 8 + wav.readUInt32LE(offset + 4)) };
+}
+const manifest = compose.loadCaptureManifest();
+compose.validateFrameSequence(manifest.frameDirectory, manifest.frames);
+const frames = fs.readdirSync(manifest.frameDirectory).sort();
+assert.strictEqual(frames.length, 1110);
+let frameBytes = 0;
+for (const [index, file] of frames.entries()) {
+  assert.strictEqual(file, `frame-${String(index + 1).padStart(4, '0')}.png`);
+  const bytes = fs.readFileSync(path.join(manifest.frameDirectory, file));
+  assert.deepStrictEqual(capture.decodePngDimensions(bytes), { width: 466, height: 466 });
+  frameBytes += bytes.length;
+}
+const narration = pcm(path.join(__dirname, base + '旁白.wav'));
+assert.strictEqual(narration.metadata.durationSeconds, 60);
+const evidence = JSON.parse(fs.readFileSync(path.join(__dirname, base + '旁白渲染清单.json'), 'utf8'));
+const reconstructed = Buffer.alloc(narration.data.length);
+const cues = evidence.cues.map((cue) => {
+  const file = path.join(__dirname, 'narration-runs', evidence.runDirectory, cue.file);
+  const selected = pcm(file);
+  const offset = cue.start * narration.metadata.byteRate;
+  assert.ok(narration.data.subarray(offset, offset + selected.data.length).equals(selected.data));
+  selected.data.copy(reconstructed, offset);
+  let peak = 0;
+  for (let i = 0; i < selected.data.length; i += 2) peak = Math.max(peak, Math.abs(selected.data.readInt16LE(i)));
+  return { index: cue.index, start: cue.start, end: cue.end, rate: cue.rate,
+    durationSeconds: selected.metadata.durationSeconds, exactPcmMatch: true, peak,
+    clipping: peak >= 32767, file };
+});
+assert.ok(reconstructed.equals(narration.data), 'Complete untrimmed cues plus zero-filled gaps reproduce the final WAV exactly');
+const final = path.join(__dirname, compose.FINAL_FILENAME);
+const metadata = ffmpeg(['-hide_banner', '-i', final], [1]).stderr;
+write('final-streams.log', metadata);
+assert.match(metadata, /Duration: 00:01:00\.00/);
+assert.match(metadata, /Video: h264.*yuv420p.*932x932/);
+assert.match(metadata, /Audio: aac/);
+assert.match(metadata, /Stream #0:2\(zho\): Subtitle: mov_text/);
+assert.strictEqual((metadata.match(/Subtitle: mov_text/g) || []).length, 1);
+const decode = ffmpeg(['-hide_banner', '-v', 'error', '-i', final, '-map', '0:v:0', '-map', '0:a:0', '-progress', 'pipe:1', '-f', 'null', '-']);
+write('final-decode.log', decode.stdout + decode.stderr);
+assert.match(decode.stdout, /frame=600/);
+const keyDirectory = path.join(__dirname, 'key-frames');
+fs.mkdirSync(keyDirectory);
+for (const seconds of [3, 15, 25, 33, 43, 51, 58]) {
+  ffmpeg(['-hide_banner', '-v', 'error', '-n', '-ss', String(seconds), '-i', final, '-frames:v', '1', path.join(keyDirectory, `final-${seconds}s.png`)]);
+}
+const files = [compose.FINAL_FILENAME, compose.MASTER_FILENAME, base + '旁白.wav', base + '字幕.srt', base + '文字稿.md', 'capture-manifest.json'];
+const artifacts = files.map((name) => {
+  const file = path.join(__dirname, name), bytes = fs.readFileSync(file);
+  return { file, bytes: bytes.length, sha256: crypto.createHash('sha256').update(bytes).digest('hex') };
+});
+const verification = { frameCount: frames.length, frameBytes, manifest, cues, artifacts,
+  narration: narration.metadata, voiceRecordedInRenderManifest: evidence.voice,
+  decodedVideoFrames: 600, keyFrameTimes: [3, 15, 25, 33, 43, 51, 58],
+  listening: 'Not performed: this model does not support audio input; no subjective intelligibility/naturalness claim.' };
+write('verification.json', JSON.stringify(verification, null, 2) + '\n');
+console.log(JSON.stringify({ frameCount: frames.length, frameBytes, cues, artifacts, decodedVideoFrames: 600 }, null, 2));
*** End Patch"));
